#!/usr/bin/env bash
# Generated By: Claude Code (Claude Opus 4.6)
# Diagnostic: collect dtach/claude process state for dashboard detection design.
# Run once per scenario (attached, detached, reattached, direct claude).
# Output goes to stdout — redirect or copy-paste results.

set -euo pipefail

SESSIONS_DIR="$HOME/.claude/sessions"

echo "=== dtach diagnostic: $(date -Iseconds) ==="
echo ""

# All dtach processes on the system
echo "--- all dtach processes ---"
pgrep -a dtach 2>/dev/null || echo "(none)"
echo ""

# All dtach sockets found under common locations
echo "--- dtach socket files ---"
find "$HOME/source" "$HOME/bin" "$HOME" -maxdepth 3 -name '.dtach-claude' 2>/dev/null || echo "(none)"
echo ""

# Unix socket kernel table for dtach
echo "--- /proc/net/unix entries for dtach-claude ---"
grep dtach-claude /proc/net/unix 2>/dev/null || echo "(none)"
echo ""

echo "--- ss unix sockets for dtach-claude ---"
ss -x 2>/dev/null | grep dtach-claude || echo "(none)"
echo ""

# Per-session details
echo "--- per-session analysis ---"
if [[ ! -d "$SESSIONS_DIR" ]]; then
    echo "no sessions directory at $SESSIONS_DIR"
    exit 0
fi

for f in "$SESSIONS_DIR"/*.json; do
    [[ -f "$f" ]] || continue

    PID=$(jq -r '.pid // empty' "$f" 2>/dev/null) || continue
    CWD=$(jq -r '.cwd // empty' "$f" 2>/dev/null) || continue
    SID=$(jq -r '.sessionId // empty' "$f" 2>/dev/null) || continue

    [[ -z "$PID" ]] && continue

    echo "SESSION: $SID"
    echo "  file: $(basename "$f")"
    echo "  pid: $PID"
    echo "  cwd: $CWD"

    # Is the PID alive?
    if ps -p "$PID" > /dev/null 2>&1; then
        echo "  alive: yes"
        echo "  process: $(ps -o comm= -p "$PID" 2>/dev/null)"

        # Parent chain (use par_pid to avoid bash readonly PPID)
        par_pid=$(ps -o ppid= -p "$PID" 2>/dev/null | tr -d ' ')
        echo "  parent_pid: $par_pid"
        par_comm=""
        par_args=""
        if [[ -n "$par_pid" ]] && [[ "$par_pid" != "0" ]]; then
            par_comm=$(ps -o comm= -p "$par_pid" 2>/dev/null || echo "?")
            par_args=$(ps -o args= -p "$par_pid" 2>/dev/null || echo "?")
            echo "  parent_comm: $par_comm"
            echo "  parent_args: $par_args"

            # Grandparent
            gpar_pid=$(ps -o ppid= -p "$par_pid" 2>/dev/null | tr -d ' ')
            if [[ -n "$gpar_pid" ]] && [[ "$gpar_pid" != "0" ]]; then
                echo "  grandparent_pid: $gpar_pid"
                echo "  grandparent_comm: $(ps -o comm= -p "$gpar_pid" 2>/dev/null || echo "?")"
                echo "  grandparent_args: $(ps -o args= -p "$gpar_pid" 2>/dev/null || echo "?")"
            fi
        fi

        # Is parent dtach?
        is_dtach="no"
        if [[ "$par_comm" == "dtach" ]]; then
            is_dtach="yes"
        fi
        echo "  parent_is_dtach: $is_dtach"

        # Check for dtach socket in session CWD
        SOCKET="$CWD/.dtach-claude"
        if [[ -S "$SOCKET" ]]; then
            echo "  dtach_socket: $SOCKET (exists)"

            # fuser: shows PIDs with socket open (key detection signal)
            echo "  fuser_output: $(fuser "$SOCKET" 2>&1 || echo "(failed)")"

            # Count unix socket connections via realpath
            real_sock=$(realpath "$SOCKET" 2>/dev/null || echo "$SOCKET")
            sock_entries=$(grep -c "$real_sock" /proc/net/unix 2>/dev/null || echo "0")
            echo "  socket_unix_entries: $sock_entries"

            # Inode of socket file
            sock_inode=$(stat -c %i "$SOCKET" 2>/dev/null || echo "?")
            echo "  socket_file_inode: $sock_inode"
        else
            echo "  dtach_socket: $SOCKET (not found)"
        fi

        # Process tree from claude up
        echo "  process_tree:"
        pstree -sap "$PID" 2>/dev/null | sed 's/^/    /' | head -8

    else
        echo "  alive: no"
    fi

    echo ""
done

# Bonus: try fuser on every dtach socket found
echo "--- fuser on all dtach sockets ---"
while IFS= read -r sock; do
    echo "  $sock: $(fuser "$sock" 2>&1 || echo "(failed)")"
done < <(find "$HOME/source" "$HOME/bin" "$HOME" -maxdepth 3 -name '.dtach-claude' -type s 2>/dev/null)
echo ""

echo "=== end diagnostic ==="
